            if path > max_path:
                max_path, max_count = path, cnt
        if y + 1 < N:
            path, cnt = dfs(x, y + 1, total + cost[x][y], count + 1)
            if path > max_path:
                max_path, max_count = path, cnt
        memo[(x, y)] = (max_path, max_count)
        return max_path, max_count

    memo = {}
    max_total, max_count = dfs(0, 0, 0, 0)
    return max_total / max_count

